INSERT INTO [game].[RoundAnswers] ([Id], [RoundId], [GamePlayerId], [AnswerType], [Text], [SubmittedAt]) VALUES
    ('ff6650e3-c322-427e-aa31-374b6c0adf18', '2fbaa2a6-16cb-4b92-9fac-255fef3cb0c2', '4e7f0b7e-7172-403a-bd41-e98cedc075d1', N'FACTUAL_REASONING', N'這件作品的外觀和同類器物有幾個共同點，但器底加工與尺寸比例仍值得再比對。我的判斷先停在合理範圍，不把一項紋飾直接當成唯一證據。', CONVERT(datetime2(3), '2026-08-27T08:08:25.1230000', 126)),
    ('2c53fdd2-1bd1-474b-b50b-b58e920f5be8', '2fbaa2a6-16cb-4b92-9fac-255fef3cb0c2', 'bfac4c45-2685-4971-92e6-addb12a3de46', N'PLAUSIBLE_FICTION', N'從紋飾節奏與器物的視覺重量來看，它可能在陳設或儀式中扮演重要角色。若要讓這個推測更可靠，還是要補上尺寸、出處和同類作品的比較結果。', CONVERT(datetime2(3), '2026-08-27T08:09:25.1230000', 126));
