INSERT INTO [social].[Events] ([Id], [EventType], [OrganizerUserId], [Title], [Content], [Location], [Latitude], [Longitude], [StartAt], [EndAt], [RegistrationEndAt], [Capacity], [ReviewStatus], [PublishStatus], [ReviewNote], [ReviewedByUserId], [ReviewedAt], [CreatedAt]) VALUES
    ('2298c774-f78d-41d4-bda4-8c869da33fa1', N'OFFICIAL', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'青銅器紋飾讀圖工作坊', N'本場從幾何紋、動物紋與器身轉折開始，帶著參加者練習把「看見的線條」和「對紋飾的推測」分開記錄。前半段會以完整影像建立觀看順序，後半段再放大器口、腹部與底部的局部，對照鑄造痕跡、構圖節奏與容易被光線掩蓋的細節。參加者不需要先熟悉專有名詞，只要帶著一個想查證的問題即可。', N'國立故宮博物院｜臺北市士林區至善路二段221號', 25.102400, 121.548500, CONVERT(datetime2(3), '2026-09-05T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-05T10:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-02T07:56:22.6770000', 126), 24, N'APPROVED', N'PUBLISHED', N'活動內容與報名資訊已確認。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-09-03T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-08-26T07:56:22.6770000', 126)),
    ('3f2bf0ea-aa9c-402c-96cf-cd308225b8dc', N'PLAYER', '11ffd7dd-c9e5-4d05-b726-2b60a56cf118', N'夜間文物猜謎會', N'活動會以局部圖像、簡短提示卡和分組討論進行三個回合；每回合先讓大家寫下看到的線索，再逐步開放材質、器形或來源提示。揭曉後不只公布答案，也會一起回看哪些判斷有圖鑑資料支持、哪些只是當下的直覺。適合想用輕鬆方式練習觀察，又願意把推理過程說出來的玩家。', N'國立故宮博物院南部院區｜嘉義縣太保市故宮大道888號', NULL, NULL, CONVERT(datetime2(3), '2026-09-25T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-25T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-22T07:56:22.6770000', 126), 30, N'PENDING', N'DRAFT', NULL, NULL, NULL, CONVERT(datetime2(3), '2026-09-15T07:56:22.6770000', 126)),
    ('ae880904-f729-4dff-8698-d3335f57776b', N'PLAYER', '15888b26-680c-4ba2-9e86-e5c8a6388fa6', N'玩家交流：我第一次看懂的細節', N'這是一場由玩家帶路的交流，大家可以分享自己在圖鑑裡第一次真正看懂的細節，也可以帶著曾經猜錯的作品來討論。流程會先用五分鐘說明作品名稱與資料來源，再交換辨識方法、查找過程和仍然沒有答案的問題；不要求每個人得出相同結論，重點是讓其他會員知道你的觀察從哪裡開始。', N'線上活動', NULL, NULL, CONVERT(datetime2(3), '2026-09-18T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-18T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-16T07:56:22.6770000', 126), 16, N'APPROVED', N'PUBLISHED', N'符合玩家交流活動規範。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-09-16T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-08T07:56:22.6770000', 126)),
    ('59879d31-aa46-4839-b3e1-e8ed8023a44c', N'OFFICIAL', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'週末館藏導讀：從器形看年代', N'本次導讀挑選三件不同時期的器物，先從通高、口徑、腹部比例與器足觀察整體形制，再回到材質、紋飾和來源欄位交叉比對。講者會示範如何保留年代原文與不確定範圍，也會安排一段讓參加者把自己的第一印象改寫成可以回查的觀察筆記，適合第一次使用圖鑑或想練習慢慢看作品的參加者。', N'國立故宮博物院南部院區｜嘉義縣太保市故宮大道888號', 23.470900, 120.294100, CONVERT(datetime2(3), '2026-09-12T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-12T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-09T07:56:22.6770000', 126), 40, N'APPROVED', N'PUBLISHED', N'已完成場次與講者資料確認。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-09-10T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-02T07:56:22.6770000', 126)),
    ('8d293743-c9a1-4478-9611-f00eb65253b0', N'PLAYER', '15888b26-680c-4ba2-9e86-e5c8a6388fa6', N'玩家提案：我的地方文物小旅行', N'這個提案想從地方博物館、歷史建築與沿線街區開始，分享一條可以實際走訪的文物小旅行。發起人預計整理交通方式、開放時間、建議停留長度、照片來源與每一站想觀察的問題，也歡迎其他會員補充自己的路線。正式成團前會先確認活動流程、集合方式與可公開使用的資料來源。', N'線上活動', NULL, NULL, CONVERT(datetime2(3), '2026-09-30T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-30T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-24T07:56:22.6770000', 126), 20, N'REJECTED', N'DRAFT', N'目前提案缺少明確的活動流程與資料來源，請補充後重新送審。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-09-28T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-20T07:56:22.6770000', 126)),
    ('be150dd2-6067-41be-8d99-f03a80a51964', N'OFFICIAL', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'古典色彩與保存觀察', N'本場會從常見顏料、釉色與表面保存狀態切入，帶領參加者比較色彩變化在辨識上的幫助與限制。除了看作品本身，也會討論拍攝光線、反光、修復痕跡和螢幕顯示可能造成的誤判，最後將一段過度肯定的描述改寫成保留證據範圍的觀察筆記。活動結束後可回到圖鑑繼續查找相關作品。', N'國立故宮博物院南部院區｜嘉義縣太保市故宮大道888號', 23.470900, 120.294100, CONVERT(datetime2(3), '2026-08-26T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-08-26T10:56:22.6770000', 126), CONVERT(datetime2(3), '2026-08-19T07:56:22.6770000', 126), 18, N'APPROVED', N'CANCELLED', N'因場地維護取消本場活動，後續將另行公告。', '4d18c9d4-d3a3-46f2-86a9-ff75cbf49487', CONVERT(datetime2(3), '2026-08-24T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-08-16T07:56:22.6770000', 126)),
    ('b096b0a3-d410-4ad3-906a-f4f5f3c0b791', N'OFFICIAL', '4134ddc4-ca89-4180-ac72-bbe0f42ab285', N'小型器物的手感與比例', N'本場從鑑定遊戲裡常見的小型器物題目延伸，先讓參加者比較不同作品的通高、口徑、器壁厚薄與可想像的拿取方式，再討論「手感」哪些可以從資料推測、哪些必須保留為想像。活動會把遊戲作答、圖鑑欄位和個人筆記放在一起回顧，練習不要只用一個醒目的特徵替作品下結論。', N'線上活動', NULL, NULL, CONVERT(datetime2(3), '2026-09-08T07:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-08T09:56:22.6770000', 126), CONVERT(datetime2(3), '2026-09-06T07:56:22.6770000', 126), 28, N'PENDING', N'DRAFT', NULL, NULL, NULL, CONVERT(datetime2(3), '2026-08-29T07:56:22.6770000', 126));
INSERT INTO [social].[SocialComments] ([Id], [PostId], [ParentCommentId], [UserId], [Content], [Status], [CreatedAt], [UpdatedAt]) VALUES
    ('f35df9b8-2851-2758-a59f-000fc471438f', 'e3179cdf-eb1f-af50-8dde-d371e9e7eb89', '6b09a231-b07b-8d5f-951a-4bfeb4033117', '32090e80-8d61-4801-b480-a6358f7a9e37', N'我會把這回合最早注意到的線索和最後採用的理由都記下來，下一次遇到相近題型時比較能看出自己真正需要練習的是觀察還是時間分配。', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-03T09:54:00.0000000', 126), CONVERT(datetime2(3), '2026-09-03T09:54:00.0000000', 126)),
    ('c8de76cc-38b8-b552-8ee9-0034f91538ab', '908f40ce-b5a7-b153-9b9f-d6f7ecbd5739', 'f25e4c59-7c2b-8f50-ac2b-76782c0ea852', '7881ef5d-547d-4d08-b71d-a48be2000a35', N'如果要繼續查證，我會先找同類作品的尺寸與來源資料，再回頭確認這裡的觀察是否能成立。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-21T08:41:00.0000000', 126), CONVERT(datetime2(3), '2026-08-21T08:41:00.0000000', 126)),
    ('a8c2cda6-fa37-235e-8312-0049f9945bdb', 'c9eacb60-647d-165d-a650-f15ba568c1da', '98a1046d-93fe-ff59-a770-db77382442f5', 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'如果能再補一個可以回查的來源、比較作品或觀看角度，這段討論就不會停在第一印象，也更方便下一位會員接著整理。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-05T00:44:00.0000000', 126), CONVERT(datetime2(3), '2026-02-05T00:44:00.0000000', 126)),
    ('51d6c03f-e602-d354-809e-00fe8088156a', 'da294627-14d1-7952-8da9-8ddc278a69de', 'b4f5a07a-648e-145e-aea3-39fe2d97c257', 'db7f8c59-6471-4604-a85c-ebc59c02fc6c', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-20T03:04:00.0000000', 126), CONVERT(datetime2(3), '2025-12-20T03:04:00.0000000', 126)),
    ('e9da6296-c8ed-9b56-a03c-019555c54128', '958c8440-1396-2f55-a591-2b2320924f6f', NULL, 'cba35abc-b074-4d30-b5ab-3b793dd62330', N'我也很有共鳴，尤其是「一天只安排兩個展區，反而有空間把筆記寫完整」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-07T08:26:00.0000000', 126), CONVERT(datetime2(3), '2025-12-07T08:26:00.0000000', 126)),
    ('3985fb6e-07c7-bd5c-a0d5-02634ccf609d', '0e94d2cc-7e36-2053-8cd9-999e278026fb', NULL, 'ce13b79f-7f78-40e1-af3b-8b20a85c610b', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-06-14T00:43:00.0000000', 126), CONVERT(datetime2(3), '2026-06-14T00:43:00.0000000', 126)),
    ('ccd91e9a-89eb-c255-8cdf-029d3731bb3c', 'd77ed3d0-ec84-1158-891a-04a0838c9c2e', 'd858cbfe-83dc-d254-9b50-8577977e588c', '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-08T11:49:00.0000000', 126), CONVERT(datetime2(3), '2026-02-08T11:49:00.0000000', 126)),
    ('b03d6dbc-5a61-df5e-84f6-032dde3d202e', 'ac06a04a-27a8-d85d-9d5c-d8f0f01a6e25', '004799e8-365b-6050-a693-1aa4eaad87c7', 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-24T09:47:00.0000000', 126), CONVERT(datetime2(3), '2026-02-24T09:47:00.0000000', 126)),
    ('06ef8b2c-b4ae-265f-b20b-0367e5ff4eb4', 'cb31c93c-8d6c-2757-a688-5ed1e297af34', '12c8b08f-2134-5559-a7a2-244b965f0c37', '43cf06a1-6472-4a3a-8334-6a5bf08879c7', N'我喜歡這篇保留不確定性的寫法，讀者可以清楚知道哪些是紀錄，哪些是作者目前的理解。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-13T09:42:00.0000000', 126), CONVERT(datetime2(3), '2026-08-13T09:42:00.0000000', 126)),
    ('ede01536-b2de-2d50-928b-048b8f0dfffb', 'ef0513a5-ea0f-d955-9d79-9474b8b79367', 'b7f53adb-d0a6-585f-b23e-946df5523ac3', 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'遊戲結束後再回到圖鑑核對，應該能分清楚哪些判斷有資料支持，哪些只是當下的直覺。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-31T10:34:00.0000000', 126), CONVERT(datetime2(3), '2025-10-31T10:34:00.0000000', 126)),
    ('2ac0b4cf-47b5-6755-af14-048c3e157933', '96690504-0727-675d-a2e0-ee0c0abc7495', NULL, '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'我也很有共鳴，尤其是「展場聲音和人流也會影響我對作品的第一印象」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-14T07:49:00.0000000', 126), CONVERT(datetime2(3), '2026-09-14T07:49:00.0000000', 126)),
    ('3f442e2b-21a5-5652-9787-04ae29539f29', '17327017-40a5-a95d-902d-9fae2b56af51', NULL, 'db7f8c59-6471-4604-a85c-ebc59c02fc6c', N'這段遊戲經驗很適合回頭檢查自己的推理順序；如果我在同一回合，會先把看見的線索說出來，再決定要不要猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-08-16T08:47:00.0000000', 126), CONVERT(datetime2(3), '2026-08-16T08:47:00.0000000', 126)),
    ('9b9a21a5-801f-e358-ab62-04edc1cbaf80', 'ea125a61-0806-bd56-8278-38b022b8d139', NULL, 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'我也很有共鳴，尤其是「如果作品只有一個角度的圖，大家會先怎麼避免過度解讀」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-18T11:30:00.0000000', 126), CONVERT(datetime2(3), '2026-07-18T11:30:00.0000000', 126)),
    ('a0bf2bad-043b-3c53-a955-04fa14c44b4a', 'fb85df44-71ce-3358-8c5c-70653b6443b9', NULL, 'e635f9ed-ff31-45e2-91da-dfdf518bd009', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-03T02:57:00.0000000', 126), CONVERT(datetime2(3), '2026-05-03T02:57:00.0000000', 126)),
    ('88d379ad-afa3-d353-ac3e-06491d604a16', '6e4bd3ab-6e5f-5b5c-974e-fde14ecd9735', NULL, '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'我剛好在另一件相近作品上遇到類似情況，表面看起來很像，但器底與尺寸比例其實差不少。這篇提供了一個很好的比較起點。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-13T02:27:00.0000000', 126), CONVERT(datetime2(3), '2026-05-13T02:27:00.0000000', 126)),
    ('47a4a511-1468-6851-8494-06b053cd9093', '94d48c6b-46b3-fc5f-9ff1-e1475252c442', '08a5f65c-da0a-4d51-a863-89cf443a4c72', '43cf06a1-6472-4a3a-8334-6a5bf08879c7', N'若是第一次到場，我還會先確認入口、樓層和報到方式；這些細節不一定適合塞進標題，但對真正要參加的人很重要。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-28T07:14:00.0000000', 126), CONVERT(datetime2(3), '2025-10-28T07:14:00.0000000', 126)),
    ('c1d25c12-a260-d250-92ce-06c07265ed4f', '26ea876d-b1ed-e85a-b8e6-9d269cb40a58', '1520019b-dbef-c458-9df2-44914bee3b1f', '4f79ced2-639d-419a-ad7e-d8027c56eceb', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-03T02:35:00.0000000', 126), CONVERT(datetime2(3), '2026-09-03T02:35:00.0000000', 126)),
    ('301d9124-79eb-df5f-b3d9-06c4f3992dcb', 'f6c34f0d-5545-6751-a235-22c138d3c113', '6152758b-2285-1a5d-959b-c11c7b6e150c', '32090e80-8d61-4801-b480-a6358f7a9e37', N'你把看見的地方和還沒有把握的部分分開寫，讀起來很舒服，也讓人知道可以從哪裡接著聊。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-17T11:00:00.0000000', 126), CONVERT(datetime2(3), '2025-12-17T11:00:00.0000000', 126)),
    ('95a3b2c5-41d1-e058-9503-07cc761e887a', '19852cde-895c-c65d-9d74-0215c96c67b2', '37602ab5-13de-a85a-a365-87e5a6647a4c', '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'我下次遇到相近的作品或情況，會先照你寫的順序看一次；如果找到不同資料，再回來補充自己看到的差異。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-18T07:05:00.0000000', 126), CONVERT(datetime2(3), '2026-01-18T07:05:00.0000000', 126)),
    ('95705dd4-f275-385d-a062-082835037adb', '0abb32d3-a338-7153-87f3-efcc1b15db73', NULL, '6cf3715d-4dac-4aeb-bbe8-0eb31d9b7d70', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-24T07:38:00.0000000', 126), CONVERT(datetime2(3), '2026-07-24T07:38:00.0000000', 126)),
    ('99e30063-5bf5-255e-bc29-0858a01c8927', '93eb8a2b-b90c-a25a-91c8-7efdfccea368', NULL, '5d5ef6cb-7ee7-4ed0-ad20-7b42e666af70', N'我也很有共鳴，尤其是「把參觀心得說給沒去過的人聽，才知道哪些背景真的需要補充」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2025-10-05T05:47:00.0000000', 126), CONVERT(datetime2(3), '2025-10-05T05:47:00.0000000', 126)),
    ('4d73efb3-ee04-7a5f-a242-08a9e83402a7', 'a516868f-b544-b95f-a620-a14626870609', NULL, 'ca5024a2-a0be-4204-8ec9-235368b494a9', N'我也會先看大觀通寶的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-29T00:25:00.0000000', 126), CONVERT(datetime2(3), '2026-05-29T00:25:00.0000000', 126)),
    ('f6a037f1-38c3-1c52-aad4-08c6824859fe', '035c641c-6eb0-8d58-a828-bf1a8f28a540', NULL, '5d5ef6cb-7ee7-4ed0-ad20-7b42e666af70', N'我也很有共鳴，尤其是「我現在會把遊戲結果當成回到圖鑑的入口，而不是最後答案」這個細節；讀完會想起自己在展場或整理照片時遇到的類似情況。', N'PUBLISHED', CONVERT(datetime2(3), '2026-09-04T05:24:00.0000000', 126), CONVERT(datetime2(3), '2026-09-04T05:24:00.0000000', 126)),
    ('f07f937a-51dc-b455-ab48-091d78c7079c', '2391f330-6ee0-3e5b-872d-653180ed3782', 'f375326d-856f-b75b-9205-a4eeaddba3e5', '59538e0b-3f85-46d0-93d6-cccb9df12831', N'如果要繼續查證，我會先找同類作品的尺寸與來源資料，再回頭確認這裡的觀察是否能成立。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-30T08:42:00.0000000', 126), CONVERT(datetime2(3), '2026-04-30T08:42:00.0000000', 126)),
    ('f9e4cef6-93f7-4b5a-9d86-0979b5804305', 'a331b6d4-cc7e-2b5d-abdb-5a26bd4f1775', NULL, 'ce13b79f-7f78-40e1-af3b-8b20a85c610b', N'我也會先看掐絲琺瑯夔龍紋簋式爐的完整輪廓，再回頭確認這篇提到的細節。把資料欄位和照片放在一起看，確實比較不容易被單一印象帶走。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-12T08:46:00.0000000', 126), CONVERT(datetime2(3), '2025-12-12T08:46:00.0000000', 126)),
    ('43c6b6aa-8064-2058-a563-0b1663a74148', 'ac484caf-fd99-f95a-b7d5-aa0929a466f7', '0252595b-ba06-b950-a660-8bfbad75657d', '9b7f2427-e62e-4229-82c3-36b1dcdd1882', N'如果前台之後提供更多互動，我希望仍然可以直接回到對應的文物、活動或訂單脈絡，而不是只看到一段沒有來源的文字。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-12T09:38:00.0000000', 126), CONVERT(datetime2(3), '2026-04-12T09:38:00.0000000', 126)),
    ('89f01341-d3e9-f65f-ba24-0b41d68ce24c', 'a875e167-b5b9-c459-a152-65e82d465121', '391c2288-64f1-bf56-8a03-d60a565512a7', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-02-21T10:33:00.0000000', 126), CONVERT(datetime2(3), '2026-02-21T10:33:00.0000000', 126)),
    ('1c6b9347-a661-d859-adc2-0b942ddbd62a', '8a2d16b2-c536-175b-9d83-6e13919d3f1a', NULL, '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'這則公告把資料整理的原則交代得很清楚，尤其是來源、推測和平台資料要分開保存，後續查閱會安心很多。', N'PUBLISHED', CONVERT(datetime2(3), '2026-07-05T05:36:00.0000000', 126), CONVERT(datetime2(3), '2026-07-05T05:36:00.0000000', 126)),
    ('4698a813-1c5a-a858-96e8-0c86800206ea', '5d2e7ea7-c9be-be5b-8399-12fe3fd31a5d', NULL, '59538e0b-3f85-46d0-93d6-cccb9df12831', N'這個整理方式很清楚，尤其是把能直接確認的部分和待查問題分開。之後如果找到新的來源，應該也比較容易知道要補在哪裡。', N'PUBLISHED', CONVERT(datetime2(3), '2025-12-04T09:47:00.0000000', 126), CONVERT(datetime2(3), '2025-12-04T09:47:00.0000000', 126)),
    ('77344c03-8150-6058-81a6-0cda5a415cca', '9e49ba45-d0fd-0c55-a3f0-7706dc2f8e3d', '412bbcdd-6f84-2e54-b816-3c79dcce8a02', '1b6805e8-d50c-40c3-8f9b-5c73ef467249', N'這個角度也很適合拿來做遊戲題目，但題幹應該保留足夠的影像或來源提示，才不會變成猜答案。', N'PUBLISHED', CONVERT(datetime2(3), '2026-04-14T10:44:00.0000000', 126), CONVERT(datetime2(3), '2026-04-14T10:44:00.0000000', 126)),
    ('45321f41-7e18-2e53-9f59-0cf7544193cf', 'd0f8799f-9cd6-ab5e-a0c1-11edbd57f145', '88210352-0ca5-1652-a6c9-29a044872398', '869ef3e0-f8cd-428c-aae4-48a75e23861a', N'如果能再補一個可以回查的來源、比較作品或觀看角度，這段討論就不會停在第一印象，也更方便下一位會員接著整理。', N'PUBLISHED', CONVERT(datetime2(3), '2026-05-18T10:15:00.0000000', 126), CONVERT(datetime2(3), '2026-05-18T10:15:00.0000000', 126)),
