INSERT INTO [store].[ProductReviews] ([Id], [ProductId], [UserId], [Rating], [Content], [Status], [CreatedAt], [UpdatedAt]) VALUES
    ('ffe855db-cad2-4e5e-8688-01507e0f27dc', '6f45fd8c-1f76-13b8-4492-b02db0bdc64a', '9b40d125-cd86-4ee1-9a12-f954c52610fb', 4, N'我把「明郭詡東山攜妓圖　軸－文物明信片」和「明郭詡東山攜妓圖　軸」的圖鑑頁放在一起看，先確認名稱與影像，再安排展示位置；商品是回到原作的入口，不是原作本身。', N'PUBLISHED', CONVERT(datetime2(3), '2026-01-19T03:00:00.0000000', 126), CONVERT(datetime2(3), '2026-01-19T03:45:00.0000000', 126)),
